/**
 * Drive's wire shapes, generated by Google from the API's Discovery document
 * (@googleapis/drive) rather than written here. Type-only: nothing of that
 * package runs. Every field is optional and may be null, because that is what
 * the schema promises. The one import in domain/, on purpose.
 */
import type { DeepReadonly } from "@foreverworks/mcp-kit";
import type { drive_v3 } from "@googleapis/drive";

export type RawFile = DeepReadonly<drive_v3.Schema$File>;
export type RawComment = DeepReadonly<drive_v3.Schema$Comment>;
export type RawReply = DeepReadonly<drive_v3.Schema$Reply>;
export type RawPermission = DeepReadonly<drive_v3.Schema$Permission>;
export type RawRevision = DeepReadonly<drive_v3.Schema$Revision>;
